mapper.select:

where sq.id = #{id}
  and coalesce(sq.shanchu_zhuangtai, '正常') = '正常'
limit 1

mapper.update:
update laoren_xinxi set lianxi_dianhua = #{xinLianxiDianhua}, jiating_zhuzhi = #{xinJiatingZhuzhi}, beizhu = #{xinBeizhu},
touxiang = #{xinTouxiang},
gengxin_shijian = now() where id = #{laorenId}

update laoren_xinxi_xiugai_shenqing
set shanchu_zhuangtai = '已删除'
where id = #{id}
